 public sealed class ActionSequenceTests {
  GameRuntime game;string directory;int frame;readonly List<float> times=new List<float>();readonly List<string> segments=new List<string>();const string Frames="/tmp/idle-design6-motion";string type;
  [UnitySetUp]public IEnumerator Setup(){directory=Path.Combine(Path.GetTempPath(),"idle-five-actions-"+Guid.NewGuid());Directory.CreateDirectory(directory);GameRuntime.SavePathOverride=Path.Combine(directory,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));for(int i=0;i<5;i++)game.Act(s=>NarrativeBridge.Action(s,"continue"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));type=ItemBalance.Items.First(i=>i.Starter==0).Id;game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Retention.gems=237;n.Story.enabled=false;n.Story.open=null;n.Story.target=null;n.Story.queue=Array.Empty<string>();n.Story.seen=NarrativeCatalog.Dialogues.Select(x=>x.Id).ToArray();n.Story.tutorial="skipped";n.Retention.aiName="AURA";n.Credits=ScientificNumber.From(50000);n.Hardware[0]=10;n.Charge=96;n.Data=ScientificNumber.From(1000000);n.Workshop.starterGift=true;n.Workshop.components=Enumerable.Repeat(500L,ItemBalance.ComponentIds.Length).ToArray();n.Workshop.learned=Enumerable.Repeat(true,ItemBalance.Items.Length).ToArray();n.Workshop.inventory=new[]{new ItemInstance{id="prepared-a",type=type,level=1},new ItemInstance{id="prepared-b",type=type,level=1}};return n;});game.Show("hardware");yield return null;game.Audio.Unlock();yield return null;yield return null;Assert.That(game.State.Story.open,Is.Null);Assert.That(GameObject.Find("AutomaticMira"),Is.Null,"No dialogue may cover the capture");}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  static void Press(Button button,bool down){Assert.That(button.interactable,Is.True,button.name);var e=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left};if(down)ExecuteEvents.Execute(button.gameObject,e,ExecuteEvents.pointerDownHandler);else ExecuteEvents.Execute(button.gameObject,e,ExecuteEvents.pointerUpHandler);if(!down)ExecuteEvents.Execute(button.gameObject,e,ExecuteEvents.pointerClickHandler);}
  void Tap(int i){var r=(RectTransform)game.TapButton.transform.parent;var p=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(new Vector2((i-1)*28,8)));var e=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left,position=p,pressPosition=p};ExecuteEvents.Execute(game.TapButton.gameObject,e,ExecuteEvents.pointerDownHandler);ExecuteEvents.Execute(game.TapButton.gameObject,e,ExecuteEvents.pointerUpHandler);ExecuteEvents.Execute(game.TapButton.gameObject,e,ExecuteEvents.pointerClickHandler);Assert.That(GameObject.Find("TapContact").GetComponent<Image>().sprite,Is.Not.Null,"First receipt render already has its authored sprite");}
  IEnumerator Record(string name,int count,Action<int> action){int start=frame;float begin=Time.realtimeSinceStartup;float minimum=name.StartsWith("01")?5:name.StartsWith("02")?3.4f:name.StartsWith("06")||name.StartsWith("07")?2:4;for(int i=0;i<count||Time.realtimeSinceStartup-begin<minimum;i++){action(i);times.Add(Time.realtimeSinceStartup);WorkshopTests.Capture(390,844,Frames+"/"+(frame++).ToString("D4")+".png");yield return null;}segments.Add(name+" "+start+" "+(frame-1));}
  [UnityTest]public IEnumerator RecordFusionFirst(){string output="/tmp/idle-fusion6-first";Directory.CreateDirectory(output);game.Act(s=>{var n=s.Copy();n.Workshop.inventory=n.Workshop.inventory.Concat(new[]{new ItemInstance{id="prepared-c",type=type,level=1}}).ToArray();return n;});game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;ui.ChangeMode("fusion");foreach(var item in game.State.Workshop.inventory.ToArray())ui.ToggleSelection(item.id);yield return null;var listener=game.GetComponent<AudioListener>();if(listener!=null)listener.enabled=false;var node=new GameObject("FusionCaptureListener",typeof(AudioListener));node.transform.SetParent(game.transform);var audio=node.AddComponent<ReviewAudioCapture>();audio.Begin();var stamps=new List<float>();for(int i=0;i<100;i++){if(i==16)Press(ui.Primary,true);if(i==20)Press(ui.Primary,false);stamps.Add(Time.realtimeSinceStartup);WorkshopTests.Capture(390,844,output+"/"+i.ToString("D4")+".png");yield return new WaitForSecondsRealtime(.025f);}Assert.That(ui.Forge.IsAnimating,Is.False);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(ui.Forge.Result.Item.id,Is.EqualTo(game.State.Workshop.inventory[0].id));audio.Save(output);File.WriteAllLines(output+"/times.txt",stamps.Select(t=>t.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));}
  [UnityTest]public IEnumerator RecordFiveActualActionsInOrder(){Directory.CreateDirectory(Frames);frame=0;times.Clear();segments.Clear();var existingListener=game.GetComponent<AudioListener>();if(existingListener!=null)existingListener.enabled=false;var listenerNode=new GameObject("ReviewMixedListener",typeof(AudioListener));listenerNode.transform.SetParent(game.transform);var audio=listenerNode.AddComponent<ReviewAudioCapture>();audio.Begin();
   yield return Record("01-tap-overdrive",85,i=>{if(i==14||i==28||i==42||i==56)Tap(i/14-1);});Assert.That(game.State.Lifetime.taps,Is.EqualTo(4));Assert.That(game.State.Overdrives,Is.EqualTo(1));
   yield return Record("02-hardware",65,i=>{var button=GameObject.Find("hardware-calculator").GetComponentsInChildren<Button>().First(b=>b.name=="HardwarePurchase");if(i==15)Press(button,true);if(i==19){var before=game.State.Credits;var cost=Game.HardwareCost(game.State,0,1);Press(button,false);Assert.That(game.State.Credits.CompareTo(before),Is.LessThan(0),"Net debit despite elapsed production tick inside Act");Assert.That(Game.HardwareCost(game.State,0,1).CompareTo(cost),Is.GreaterThan(0));var saved=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(saved.State.Hardware[0],Is.EqualTo(11));}});Assert.That(game.State.Hardware[0],Is.EqualTo(11));var income=Game.Income(game.State);
   game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(type));yield return null;var q=Workshop.Quote(game.State,type);var stock=(long[])game.State.Workshop.components.Clone();
   yield return Record("03-craft",90,i=>{if(i==15)Press(ui.Primary,true);if(i==19){Press(ui.Primary,false);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(3));for(int c=0;c<stock.Length;c++)Assert.That(game.State.Workshop.components[c],Is.EqualTo(stock[c]-(long)q.Components[c]));Assert.That(ui.Forge.FlightCount,Is.EqualTo(q.Components.Count(n=>n>0)));var persisted=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(persisted.State.Workshop.inventory.Length,Is.EqualTo(3),"Saved before motion ends");}});Assert.That(ui.Forge.IsAnimating,Is.False);Assert.That(ui.Forge.Inputs.Count(p=>p.gameObject.activeSelf),Is.EqualTo(q.Components.Count(n=>n>0)),"Unused material sockets stay hidden after completion");
   ui.ChangeMode("fusion");yield return null;string[] ids=game.State.Workshop.inventory.Select(x=>x.id).ToArray();foreach(var id in ids){GameObject.Find("item-"+id).GetComponentInChildren<ItemPortrait>().Button.onClick.Invoke();yield return null;}var expected=Workshop.FusionResult(game.State,ids);Assert.That(expected,Is.Not.Null);
   yield return Record("04-fusion",90,i=>{if(i==15)Press(ui.Primary,true);if(i==19){var origins=ui.Forge.Inputs.Select(p=>p.Frame.transform.position).ToArray();Press(ui.Primary,false);var sequence=UnityEngine.Object.FindFirstObjectByType<ForgeSequence>();Assert.That(sequence.Elapsed,Is.LessThan(.02f),"Animation starts at its receipt time, never at the previous save frame duration");for(int n=0;n<3;n++){Assert.That(Vector3.Distance(origins[n],sequence.Sources[n].Frame.transform.position),Is.LessThan(12),"Actual selected items begin at their own socket without a layout jump");Assert.That(sequence.Sources[n].Item.id,Is.EqualTo(ids[n]));}Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(ui.Forge.FlightCount,Is.EqualTo(3));Assert.That(ui.Forge.Result.Item.id,Is.EqualTo(expected.id));}});Assert.That(ui.Forge.IsAnimating,Is.False);Assert.That(ui.Forge.Result.Item.rarity,Is.EqualTo(1));Assert.That(ui.Forge.Result.Frame.color,Is.EqualTo(ItemPortrait.RarityColor(1)));
   ui.ChangeMode("inventory");yield return null;GameObject.Find("item-"+expected.id).GetComponentInChildren<ItemPortrait>().Button.onClick.Invoke();yield return new WaitForSecondsRealtime(.45f);string chosen=Workshop.EquipmentSlot(game.State,expected.id);
   yield return Record("05-equip",85,i=>{var b=ui.DetailActions.GetComponentsInChildren<Button>().FirstOrDefault(x=>x.name=="equip-"+chosen);if(i==15)Press(b,true);if(i==19){Press(b,false);Assert.That(game.State.Workshop.equipped.Contains(expected.id),Is.True);Assert.That(ui.GetComponent<EquipFlight>().IsAnimating,Is.True);}});Assert.That(ui.GetComponent<EquipFlight>().IsAnimating,Is.False);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(game.State.Lifetime.itemsFused,Is.EqualTo(1));var load=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(load.Writable,Is.True);Assert.That(load.State.Workshop.equipped.Contains(expected.id),Is.True);Assert.That(load.State.Legacy.prepared,Is.True);
   yield return Record("06-model",45,i=>{});GameObject.Find("Menu").GetComponent<Button>().onClick.Invoke();yield return null;yield return Record("07-menu",50,i=>{});game.GetComponent<GameMenu>().Close();audio.Save(Frames);File.WriteAllLines(Frames+"/times.txt",times.Select(t=>t.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));File.WriteAllLines(Frames+"/segments.txt",segments);Debug.Log("FIVE_ACTIONS persisted craft=1 fusion=1 hardware=1 taps=4 equip="+chosen+" incomeBeforeEquip="+income+" incomeAfter="+Game.Income(game.State));
  }
  [UnityTest]public IEnumerator ChromeAndActionsAtMobileSizes(){string output="/tmp/idle-design6-review";Directory.CreateDirectory(output);foreach(var language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));game.Show("hardware");yield return new WaitForSecondsRealtime(.45f);var safe=game.GetComponent<MobileShell>().Laboratory.GetComponentInParent<SafeArea>().transform;Assert.That(safe.Find("Resources").GetComponent<Image>().sprite,Is.Null);foreach(var tab in safe.Find("Tabs").GetComponentsInChildren<Button>())Assert.That(tab.GetComponent<Image>().sprite,Is.Null);foreach(var width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/labor-"+language+"-"+width+".png");Assert.That(game.Users.text,Is.EqualTo(NumberFormatting.Format(ScientificNumber.From(game.State.Retention.gems),game.State.Settings.numberFormat)),"Rendered resource binding is actual Gems");yield return null;}game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(type));ui.Primary.onClick.Invoke();yield return new WaitForSecondsRealtime(2.4f);foreach(var width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/craft-"+language+"-"+width+".png");yield return null;}ui.ChangeMode("inventory");yield return null;ui.OpenItem(game.State.Workshop.inventory.Last().id);yield return new WaitForSecondsRealtime(.45f);foreach(var width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/detail-"+language+"-"+width+".png");yield return null;}}
  }
  [UnityTest]public IEnumerator MenuGemsAndConnectedModelAreReachable(){string output="/tmp/idle-design6-review";Directory.CreateDirectory(output);foreach(var language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));game.Show("hardware");yield return null;yield return null;Assert.That(game.Users.text,Is.EqualTo(NumberFormatting.Format(ScientificNumber.From(game.State.Retention.gems),game.State.Settings.numberFormat)));GameObject.Find("Menu").GetComponent<Button>().onClick.Invoke();yield return null;Assert.That(game.GetComponent<GameMenu>().IsOpen,Is.True);foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/menu-"+language+"-"+width+".png");yield return null;}GameObject.Find("Menu-settings").GetComponent<Button>().onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("settings"));GameObject.Find("Menu").GetComponent<Button>().onClick.Invoke();yield return null;GameObject.Find("Menu-production").GetComponent<Button>().onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("production"));Assert.That(UnityEngine.Object.FindFirstObjectByType<ProductionView>(),Is.Not.Null);game.Show("hardware");yield return null;game.GetComponent<MobileShell>().Laboratory.ModelButton.onClick.Invoke();yield return null;Assert.That(game.CurrentTab,Is.EqualTo("items"));Assert.That(game.WorkshopView.Mode,Is.EqualTo("inventory"));game.Act(s=>Workshop.Equip(s,"prepared-a"));yield return null;yield return null;var model=UnityEngine.Object.FindFirstObjectByType<ModelLoadout>();Assert.That(model,Is.Not.Null);Assert.That(model.Core.sprite,Is.EqualTo(game.ModelPrefab.ModelArt));Assert.That(model.Network.GetComponentsInChildren<ItemPortrait>().Length,Is.EqualTo(6));var metrics=Resources.Load<ItemArtMetrics>("PixelUI/ItemArtMetrics");Assert.That(metrics.Sprites.Length,Is.EqualTo(ItemBalance.Items.Length));foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/model-"+language+"-"+width+".png");yield return null;}}}
  [UnityTest]public IEnumerator FusionRevealIsReadableInBothLanguagesAndRetainsBestLevel(){string output="/tmp/idle-design6-review";Directory.CreateDirectory(output);foreach(var language in new[]{"de","en"}){game.Act(s=>{var n=SettingsRules.Change(s,"language",language).Copy();n.Workshop.equipped=new string[8];n.Workshop.inventory=new[]{new ItemInstance{id="fusion-mobile-0",type=type,level=5},new ItemInstance{id="fusion-mobile-1",type=type,level=8},new ItemInstance{id="fusion-mobile-2",type=type,level=3}};return n;});game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;ui.ChangeMode("fusion");foreach(var item in game.State.Workshop.inventory.ToArray())ui.ToggleSelection(item.id);ui.Primary.onClick.Invoke();Assert.That(game.State.Workshop.inventory.Single().id,Is.EqualTo("fusion-mobile-1"));Assert.That(game.State.Workshop.inventory.Single().level,Is.EqualTo(8));yield return new WaitForSecondsRealtime(1.5f);var sequence=UnityEngine.Object.FindFirstObjectByType<ForgeSequence>();Assert.That(sequence.Hero.gameObject.activeInHierarchy,Is.True);Assert.That(sequence.Hero.Item.id,Is.EqualTo(game.State.Workshop.inventory.Single().id));Assert.That(sequence.Hero.Frame.color,Is.EqualTo(ItemPortrait.RarityColor(1)));Assert.That(sequence.Improvement.text,Does.Contain("→"));Assert.That(ui.Primary.GetComponentInChildren<Text>().text,Is.EqualTo(language=="de"?"Sofort fusionieren":"Fuse instantly"));if(language=="en")Assert.That(ui.RecipeTitle.text,Does.Not.Contain("drei"));foreach(int width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/fusion-"+language+"-"+width+".png");yield return null;}yield return new WaitForSecondsRealtime(1.2f);Assert.That(ui.Forge.IsAnimating,Is.False);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));}}
  [UnityTest]public IEnumerator EightMaterialReceiptIsBoundedAndSavedBeforeCancellation(){var definition=ItemBalance.Items.First(d=>d.Components[0].Count(n=>n>0)==8);game.Act(s=>{var n=s.Copy();n.Data=ScientificNumber.From(1e30);n.Research[Array.FindIndex(Balance.Research,r=>r.Id=="blueprints")]=1;n.Workshop.components=Enumerable.Repeat(1000000000L,ItemBalance.ComponentIds.Length).ToArray();n.Workshop.modules=Enumerable.Repeat(1000000000L,ItemBalance.Modules.Length).ToArray();return n;});game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(definition.Id));Assert.That(ui.Primary.interactable,Is.True);ui.Primary.onClick.Invoke();Assert.That(ui.Forge.FlightCount,Is.EqualTo(8));Assert.That(ui.Forge.IsAnimating,Is.True);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(3));Assert.That(UnityEngine.Object.FindFirstObjectByType<ForgeSequence>().GetComponentsInChildren<ItemPortrait>(true).Length,Is.LessThanOrEqualTo(9));game.HardwareTab.onClick.Invoke();yield return null;Assert.That(UnityEngine.Object.FindFirstObjectByType<ForgeSequence>(),Is.Null);var saved=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(saved.State.Workshop.inventory.Length,Is.EqualTo(3));}

  [UnityTest]public IEnumerator OffscreenEquipmentTargetBecomesVisibleAndMenuRestoresInventoryMode(){game.Act(s=>{var n=s.Copy();n.Workshop.inventory=n.Workshop.inventory.Concat(Enumerable.Range(0,40).Select(i=>new ItemInstance{id="prepared-scroll-"+i,type=type,level=1})).ToArray();return n;});game.Show("items");yield return null;var ui=game.WorkshopView;ui.ChangeMode("inventory");yield return null;var scroll=game.Content.GetComponentInParent<ScrollRect>();Canvas.ForceUpdateCanvases();scroll.verticalNormalizedPosition=0;Canvas.ForceUpdateCanvases();var target=ui.Equipment.GetComponentsInChildren<ItemPortrait>().First(p=>p.name=="equipment-processor");Assert.That(scroll.viewport.rect.Contains((Vector2)scroll.viewport.InverseTransformPoint(target.Frame.transform.position)),Is.False);ui.OpenItem("prepared-a");ui.DetailActions.GetComponentsInChildren<Button>().First(b=>b.name=="equip-processor").onClick.Invoke();yield return null;target=ui.Equipment.GetComponentsInChildren<ItemPortrait>().First(p=>p.name=="equipment-processor");Assert.That(scroll.viewport.rect.Contains((Vector2)scroll.viewport.InverseTransformPoint(target.Frame.transform.position)),Is.True,"Actual destination is visible before its item flies");yield return new WaitForSecondsRealtime(1.2f);Assert.That(game.State.Workshop.equipped,Does.Contain("prepared-a"));scroll.verticalNormalizedPosition=.25f;game.GetComponent<GameMenu>().Open();yield return null;GameObject.Find("Menu-settings").GetComponent<Button>().onClick.Invoke();yield return null;GameObject.Find("MenuReturn").GetComponent<Button>().onClick.Invoke();yield return null;Assert.That(game.WorkshopView.Mode,Is.EqualTo("inventory"));Assert.That(scroll.verticalNormalizedPosition,Is.EqualTo(.25f).Within(.02f));}
  [UnityTest]public IEnumerator RapidRepeatCancelReducedAndReloadStayExactlyOnce(){game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(type));for(int i=0;i<5;i++)ui.Primary.onClick.Invoke();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(7));Assert.That(ui.Forge.PresentedCount,Is.EqualTo(5),"Rapid cosmetic receipts compact actual saved results");Assert.That(UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Count(t=>t.name.StartsWith("ComponentFlight")),Is.LessThanOrEqualTo(20));ui.ChangeMode("inventory");yield return null;Assert.That(ui.Forge.IsAnimating,Is.False);ui.OpenItem("prepared-a");ui.DetailActions.GetComponentsInChildren<Button>().First(b=>b.name.StartsWith("equip-")).onClick.Invoke();game.HardwareTab.onClick.Invoke();yield return new WaitForSecondsRealtime(.8f);Assert.That(GameObject.Find("EquipmentFlightLayer"),Is.Null);game.Act(s=>{var n=s.Copy();n.Settings.effects=false;n.Workshop.reducedMotion=true;return n;});game.ItemsTab.onClick.Invoke();yield return null;ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(type));ui.Primary.onClick.Invoke();Assert.That(ui.Forge.IsAnimating,Is.False);Assert.That(ui.Forge.Result.Item.id,Is.EqualTo(game.State.Workshop.inventory.Last().id));ui.ChangeMode("inventory");ui.OpenItem("prepared-b");ui.DetailActions.GetComponentsInChildren<Button>().First(b=>b.name.StartsWith("equip-")).onClick.Invoke();Assert.That(ui.GetComponent<EquipFlight>().IsAnimating,Is.False);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(8));Assert.That(game.State.Workshop.equipped.Contains("prepared-b"),Is.True);Assert.That(game.State.Settings.effects,Is.False);}
